'use strict';
function reportTable(rows){return '<table class="report-table"><tbody>'+rows.map(([a,b,c])=>`<tr><td>${a}</td><td>${b}</td>${c===undefined?'':'<td>'+c+'</td>'}</tr>`).join('')+'</tbody></table>'}
function companyAccounts(){return `<div class="report-page report-cover"><div class="company-wordmark"><svg width="46" height="46" viewBox="0 0 46 46" aria-hidden="true"><rect x="1" y="1" width="44" height="44" fill="none" stroke="currentColor"/><path d="m8 33 12-20 7 11 4-6 8 15M17 20l3 4 3-4" fill="none" stroke="currentColor"/></svg><span>2LR<br><small>INVESTMENTS LTD</small></span></div><span class="report-draft">ILLUSTRATIVE DRAFT · NOT FOR SUBMISSION</span><h1>Annual report<br>and financial statements</h1><p class="report-period">For the year ended 31 March 2026</p><div class="report-cover-details"><p>Private company limited by shares</p><p>Company number: 00000000 · fictional placeholder<br>Registered office: to be completed before filing</p><p>Prepared in <span class="report-ron">ron<span>.</span></span><br>For professional review and director approval</p></div><p class="report-small">This complete example pack is a product mock-up. It is not statutory filing software, an accountant’s assurance report, a tax computation or a filing-ready set of accounts. Accounting framework, exemptions, identifiers, disclosures and signatures require professional completion.</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Company information and contents</h2>${reportTable([['Director','Will Hackett · illustrative'],['Company secretary','Not appointed in this example'],['Company number','00000000 · fictional'],['Registered office','Required before submission'],['Accountant','Appointed Partner · example only'],['Reporting period','1 April 2025 to 31 March 2026']])}<h3>Contents</h3><ol><li>Director’s report and responsibilities</li><li>Statement of income</li><li>Statement of financial position</li><li>Cash flow working statement</li><li>Notes to the financial statements</li><li>Review and approval record</li></ol><p class="report-small">Reporting-date figures differ from the app’s later 17 October 2026 investment snapshot. All comparative figures are illustrative. This is a full review pack; the statutory material required for Companies House depends on the company’s eligibility and filing regime.</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Director’s report</h2><h3>Principal activity</h3><p>The company holds and manages investments funded by share capital, retained earnings and interest-free shareholder loans. This example assumes investment administration rather than an active trading business.</p><h3>Results and distributions</h3><p>Profit for the year after tax is £41,500 (2025: £31,500). No dividends were declared in the illustrated year. The profit is retained.</p><h3>Funding and liquidity</h3><p>Cash at 31 March 2026 was £150,000. Shareholder loan principal of £2,385,500 is presented within creditors falling due within one year in this example. The directors must assess the actual loan terms, availability of financial support and the going-concern basis before approval.</p><h3>Director’s responsibilities</h3><p>The directors are responsible for selecting appropriate accounting policies, maintaining adequate records, assessing the company’s ability to continue as a going concern and approving accounts that meet the applicable requirements.</p><h3>Audit and accounting framework</h3><p>Audit status and the accounting framework are not established by this mock-up. No audit opinion or exemption statement is asserted. A professional must determine eligibility and include the required wording and disclosures.</p><p>Director signature: __________________<br>Name: Will Hackett · sample<br>Approval date: not signed</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Statement of income</h2><p>For the year ended 31 March 2026 · amounts in GBP</p>${reportTable([['','2026','2025'],['Investment income','68,000','52,000'],['Administrative expenses','(12,000)','(10,000)'],['Profit before tax','56,000','42,000'],['Current tax charge','(14,000)','(10,500)'],['Prior-period tax adjustment','(500)','—'],['Profit after tax','41,500','31,500']])}<h3>Statement of changes in equity</h3>${reportTable([['','2026','2025'],['Opening equity','308,500','277,000'],['Profit after tax','41,500','31,500'],['Dividends','—','—'],['Closing equity','350,000','308,500']])}<p class="report-small">Illustrative investment income comprises £20,000 interest and £48,000 taxable fund returns. No exempt ordinary-dividend receipt is assumed in this sample income statement. Actual distribution classifications and expense deductibility need review.</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Statement of financial position</h2><p>As at 31 March 2026 · amounts in GBP</p>${reportTable([['','2026','2025'],['Investments','2,600,000','2,440,000'],['Cash at bank','150,000','210,000'],['Total assets','2,750,000','2,650,000'],['Shareholder loans due within one year','(2,385,500)','(2,331,000)'],['Tax creditor','(14,500)','(10,500)'],['Total creditors','(2,400,000)','(2,341,500)'],['Net assets','350,000','308,500'],['Share capital','1,000','1,000'],['Retained earnings','349,000','307,500'],['Total equity','350,000','308,500']])}<p>The financial statements remain unsigned. Statutory declarations, applicable audit-exemption statements and approval wording must be completed by the appointed professional before any filing.</p><p>Approved by the board: not yet approved<br>Signed on behalf of the board: __________________</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Cash flow working statement</h2><p>For the year ended 31 March 2026 · illustrative working schedule</p>${reportTable([['Profit after tax','41,500'],['Increase in tax creditor','4,000'],['Operating cash flow','45,500'],['Net investment purchases','(160,000)'],['Net shareholder funding','54,500'],['Net decrease in cash','(60,000)'],['Opening cash','210,000'],['Closing cash','150,000']])}<h3>Reconciliation</h3><p>£45,500 − £160,000 + £54,500 = a £60,000 decrease in cash. Loan principal is financing, not a deductible administrative expense. No loan interest is assumed.</p><p class="report-small">This schedule is included to explain the example. Whether it is a required statutory statement depends on the accounting framework and company eligibility; neither is determined here.</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Notes to the financial statements</h2><h3>1. Basis of preparation</h3><p>GBP illustrative historical reporting snapshot. Framework, measurement policies, impairment assessment, related-party requirements and going-concern evidence must be selected and documented by the appointed accountant. No FRS 105 eligibility is assumed.</p><h3>2. Investments</h3><p>Investments total £2,600,000. The reporting pack needs a reconciled schedule of quantities, costs, measurement bases, valuations and disposals, with any controlled-company interests distinguished from the underlying assets.</p><h3>3. Tax</h3><p>The illustrative current-year charge is £14,000, with a £500 prior-period adjustment. The tax creditor is £14,500. This is not a CT600 computation. Dividend exemptions, taxable interest and fund returns, gains, losses and expense claims need separate classification.</p><h3>4. Shareholder funding</h3>${reportTable([['Will Hackett · principal','2,085,500'],['Other shareholder · principal','300,000'],['Total shareholder loans','2,385,500']])}<p>Loans are interest-free in this example. Presentation assumes amounts are repayable on demand; actual signed terms and any financial-support undertakings require review. The later app snapshot shows £2,400,000 of shareholder principal at a different date.</p><h3>5. Share capital</h3><p>1,000 ordinary shares with an illustrative nominal value of £1 each. Rights, ownership and register entries must be verified.</p><h3>6. Commitments, contingencies and subsequent events</h3><p>Not assessed in this prototype. The directors and professional must complete the necessary enquiries and disclosures. A blank assessment is not a statement that none exist.</p></div>
<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><h2>Review and approval record</h2><p>Two supporting records remain outstanding in this example. Viewing this report does not clear those tasks.</p>${reportTable([['Reporting-date broker statement','Outstanding'],['Shareholder balance confirmations','Outstanding'],['Tax classification and computation','Professional review required'],['Company identifiers and statutory wording','Incomplete'],['Accountant review','Not complete'],['Director approval','Not signed'],['Companies House submission','Not submitted'],['Submission receipt','None']])}<p class="report-small">ron. branding identifies the preparation workspace. Company branding is presentation only; it does not replace required statutory content. This example must not be submitted as actual company accounts.</p></div>`}
function personalReturn(){return `<div class="report-page report-cover"><span class="report-ron">ron<span>.</span></span><span class="report-draft">ILLUSTRATIVE PERSONAL RETURN · NOT FOR SUBMISSION</span><h1>Personal tax return<br>review pack</h1><p class="report-period">Will Hackett · 6 April 2025 to 5 April 2026</p><p>Taxpayer identifiers: not provided<br>Appointed tax agent: not confirmed<br>Submission status: not submitted</p><p class="report-small">A complete illustrative review schedule, not a completed HMRC SA100, an iXBRL filing or a final tax computation. Actual return boxes, supplementary pages, source evidence and authorisations must be completed by a professional.</p></div><div class="report-page"><div class="report-running">PERSONAL TAX REVIEW <span>ron.</span></div><h2>Income and gains schedule</h2>${reportTable([['Employment income','112,000'],['UK interest','2,400'],['Dividend income','8,000'],['Share disposal proceeds','125,000'],['Allowable costs on disposals','96,000'],['Illustrative net gain before reliefs','29,000'],['Loan principal repayments received','90,000 · capital, separately recorded']])}<h3>Reliefs and evidence</h3><p>Pension contributions, employee share events, loss claims and relief certificates remain subject to evidence and eligibility review. No investment relief is assumed merely because a document was uploaded.</p><h3>Tax payment schedule</h3>${reportTable([['Illustrative capital-gains element','6,400'],['Other personal tax balance','11,800'],['Illustrative balance to plan for','18,200'],['Payments on account','Not included; assessment required'],['Online filing / balancing deadline','31 January 2027']])}<p class="report-small">The £18,200 is an illustrative draft balance after unspecified withholding and prior payments, not a calculation from the gross income schedule above. PAYE credits, reliefs, losses, gains treatment and prior payments must be reconciled before approval.</p></div><div class="report-page"><div class="report-running">PERSONAL TAX REVIEW <span>ron.</span></div><h2>Evidence and authorisation</h2>${reportTable([['P60 / employment income','Required'],['Interest and dividend certificates','Review required'],['Disposal ledger and contract notes','Review required'],['Loan principal records','Review required'],['Professional review','Not complete'],['Client approval','Not granted'],['Tax agent authority','Must be confirmed'],['Submission and receipt','None']])}<p>No actual personal return has been prepared or filed by this prototype. The accountant must supply the final return and computation for the client’s approval.</p></div>`}
function confirmationStatement(){return `<div class="report-page"><div class="report-running">2LR INVESTMENTS LTD <span>ron.</span></div><span class="report-draft">ILLUSTRATIVE COMPANY DETAILS REVIEW · NOT AN OFFICIAL CS01</span><h1>Confirmation statement</h1><p class="report-period">Review period ending 15 November 2026</p>${reportTable([['Company','2LR Investments Ltd'],['Company number','00000000 · fictional'],['Review date','15 November 2026'],['Example filing deadline','29 November 2026'],['Share capital','1,000 ordinary £1 shares'],['Shareholders','Household · sample register'],['Registered office','Verify against the actual register'],['Officers and PSC details','Professional verification required'],['Identity verification requirements','Must be checked before submission'],['Submission status','Not submitted']])}<h3>What you are checking</h3><p>Whether the company’s registered details, officers, share capital and ownership information agree with the actual register. Changes and any required identity verification must be resolved before a real submission.</p><p class="report-small">This is a complete mock review screen, not a completed statutory form. The sample does not contain verified company identifiers, officer details or PSC information. No filing can be made from it.</p><label class="checkbox"><input type="checkbox" id="confirm-draft"> I’ve checked these sample details.</label><button class="primary wide" id="approve-draft" disabled>Approve sample review (demo)</button><p class="report-small">Local demonstration only. This does not sign, authorise or send an actual confirmation statement.</p></div>`}
function fullFiling(type){const dialog=$('#simple-dialog'),title=type==='personal'?'Personal return':type==='confirmation'?'Company details':'Company accounts',summary=type==='personal'?'£18,200 illustrative tax balance':type==='confirmation'?'Company details to confirm · due 29 November':'£350,000 net assets · £41,500 profit after tax',slug=type==='personal'?'personal-return':type==='confirmation'?'confirmation-statement':'company-accounts';dialog.classList.add('full-report');open(`<div class="report-toolbar"><button class="secondary" id="close-report">← Back</button><strong>${title} · full example</strong><a class="text-link" href="/documents/${slug}.html" target="_blank" rel="noopener">Open standalone ↗</a></div><div class="report-summary"><strong>${summary}</strong><span>${type==='confirmation'?'Illustrative sample review · no actual submission':'Draft example · professional checks incomplete · approval disabled'}</span></div><div class="report-stack">${type==='personal'?personalReturn():type==='confirmation'?confirmationStatement():companyAccounts()}</div>`);$('#close-report').onclick=close;dialog.scrollTop=0;if(type==='confirmation'){$('#confirm-draft').onchange=e=>$('#approve-draft').disabled=!e.target.checked;$('#approve-draft').onclick=()=>{if(!state.approved.includes('cs'))state.approved.push('cs');persist();close();render();note('Sample review approved locally. Nothing was filed.')}}}
$('#simple-dialog').addEventListener('close',()=>$('#simple-dialog').classList.remove('full-report'));
